// Row shape: [question, correct answer, explanation, difficulty, [three distractors]].
const row = (q, answer, why, difficulty, distractors) => [q, answer, why, difficulty, distractors];
const buildWorld = (worldId, chapters) => {
  const meta = WORLD_META[worldId];
  const records = [];
  for (let chapterIndex = 0; chapterIndex < chapters.length; chapterIndex++) {
    const [topicId, subtopic, sourceKey, sourceId, answerFamily] = meta[chapterIndex];
    for (const item of chapters[chapterIndex]) {
      const [q, correctText, why, difficulty, distractorTexts] = item;
      const id = `${worldId}-extra-${String(21 + records.length).padStart(3, '0')}`;
      records.push({
        id, q, correctText, why, difficulty, topicId, subtopic, chapterId:chapterIndex + 1,
        answerFamily,
        distractors:distractorTexts.map(text => ({
          text,
          rationale:`${text} is a different ${answerFamily}; it does not match the clue asking about ${subtopic.toLowerCase()}.`,
        })),
        source:{
          title:SOURCES[worldId][sourceId].title,
          url:SOURCES[worldId][sourceId].url,
          claim:`${q} The intended answer is ${correctText}. ${why}`,
          status:'needs-review',
        },
      });
    }
  }
  if (records.length !== 80) throw new Error(`${worldId}: expected 80 additions, found ${records.length}`);
  return records;
};

